# environments/prod/backend.tf
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }
  }
  backend "s3" {
    bucket         = "acme-tfstate-prod"
    key            = "network/terraform.tfstate"
    region         = "ap-northeast-1"
    dynamodb_table = "acme-tflock"   # 锁表，主键 LockID(String)
    encrypt        = true              # SSE-S3 加密 state
  }
}

# environments/prod/main.tf
module "vpc" {
  source  = "git::https://github.com/acme/tf-modules.git//vpc?ref=v1.2.0"
  name    = "prod-vpc"
  cidr    = "10.20.0.0/16"
  azs     = ["ap-northeast-1a", "ap-northeast-1c"]
}

resource "aws_db_instance" "orders" {
  identifier     = "orders-prod"
  engine         = "mysql"
  instance_class = "db.r6g.large"
  allocated_storage = 100
  lifecycle {
    prevent_destroy       = true     # 误删 RDS 时 plan 直接报错
    create_before_destroy = false    # RDS 不支持双跑，必须先删后建
    ignore_changes        = [password]  # 密码走 SSM 不进 state diff
  }
}

output "vpc_id" {
  value = module.vpc.vpc_id
}
